SELECT bbp.bill_pay_id AS billPayId, bbp.org_id AS payeeOrgId, bbp.payee_date AS payeeDate, IFNULL(bbps.received_amount, 0) AS receivedAmount, IFNULL(bbps.free_amount, 0) AS freeAmount, IFNULL(bbps.swipe_workload, 0) AS swipeWorkload, bb.org_id AS billOrgId, bb.bill_id AS billId, bb.bill_date AS billDate, bbps.executor_id AS executorId FROM base_bill_pay bbp LEFT JOIN ( SELECT bill_pay_id, executor_id, SUM(received_amount + free_amount) AS received_amount, SUM(free_amount) AS free_amount, SUM(swipe_workload) AS swipe_workload FROM base_bill_pay_share
AND executor_id > 0
AND executor_id is null
GROUP BY bill_pay_id
, executor_id
) bbps ON bbp.bill_pay_id = bbps.bill_pay_id INNER JOIN ( SELECT bb.org_id, bb.bill_id, bb.bill_date, bb.actual_amount FROM base_bill bb
AND bb.bill_date IS NOT NULL
AND bb.org_id IN
#{item}
) bb ON bbp.bill_id = bb.bill_id
AND DATE_FORMAT(bbp.payee_date, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT(bbp.payee_date, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT(bbp.payee_date, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT(bbp.payee_date, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT(bbp.payee_date, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT(bbp.payee_date, '%Y' ) <= #{query.endDate}

SELECT bbps.month, bb.bill_id AS billId, bb.org_id AS billOrgId, IFNULL(bbps.swipe_workload,0) AS swipeWorkload, IFNULL(bbps.received_amount, 0) AS receivedAmount, IFNULL(bbps.free_amount, 0) AS freePayAmount FROM ( SELECT bill_id,
DATE_FORMAT(pay_date,'%Y-%m-%d') AS month,
DATE_FORMAT(pay_date,'%Y-%m') AS month,
DATE_FORMAT(pay_date,'%Y') AS month,
SUM(received_amount + free_amount) AS received_amount, SUM(free_amount) AS free_amount, SUM(swipe_workload) AS swipe_workload FROM base_bill_pay_share
AND executor_id > 0
AND executor_id is null
AND DATE_FORMAT(pay_date, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT(pay_date, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT(pay_date, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT(pay_date, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT(pay_date, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT(pay_date, '%Y' ) <= #{query.endDate}
GROUP BY bill_id, month ) bbps INNER JOIN ( SELECT bb.org_id, bb.bill_id, bb.bill_date, bb.actual_amount FROM base_bill bb
AND bb.bill_date IS NOT NULL AND bb.actual_amount > 0
AND bb.org_id IN
#{item}
) bb ON bbps.bill_id = bb.bill_id
AND bbps.received_amount > 0
group by bb.bill_id, bb.org_id, month

SELECT bti.item_name AS itemName, bti.item_num AS itemNum, bti.category_name AS categoryName, bbps.payDate AS payeeDate, DATE_FORMAT(bb.bill_date, '%Y-%m-%d') AS billDate, bb.bill_num AS billNum, bbd.quantity, bem.employee_name AS regDentistName, be.employee_name AS executorName, IFNULL(bbps.received_amount, 0) AS amount, IFNULL(bbps.free_amount, 0) AS freePaymentAmount, bb.bill_id AS billId, if(bb.privilege_date=bbps.payDate,TRUNCATE(IFNULL(bbd.coupon_workload,0),2),0) AS supplyWorkload, bp.NAME AS patientName, bp.patient_id AS patientId, bp.mobile, bo.abbreviation FROM base_bill_detail bbp LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id INNER JOIN ( SELECT bill_pay_id, SUM(received_amount) AS received_amount, SUM(free_amount) AS free_amount FROM base_bill_pay_share bbps LEFT JOIN base_bill_pay
