GROUP BY bill_pay_id ) bbps ON bbps.bill_pay_id = bbd.bill_detail_id LEFT JOIN base_treatment_process btp ON bb.treatment_id = btp.treatment_id LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN base_organization bo ON bo.org_id = bbd.org_id LEFT JOIN base_employee bem ON btp.registered_dentist_id = bem.user_id LEFT JOIN base_employee be ON bbd.executor_id = be.user_id LEFT JOIN base_tariff_info bti ON bbd.item_id = bti.item_id AND bbd.item_type = bti.item_type
bb.bill_date IS NOT NULL
and bbd.item_id in
#{item}
